1	//! Translate a validated `Config` + scenario + built artifacts
2	//! into a deterministic `LoadPlan`, then into the `cor24-run`
3	//! command line. Step 008 covers Scenario A; later steps add B/C
4	//! patches and composite-image emission.
5	//!
6	//! The plan is *deterministic*: memory loads come out address-
7	//! ascending regardless of TOML declaration order, patches come
8	//! out address-ascending too. UART chunks preserve the scenario's
9	//! declared order (the order matters for the `<source> + EOT +
10	//! <stdin>` pattern from `docs/survey/ocaml.md`).
11	//!
12	//! Embedded segments (e.g. `pvm.s`'s `eval_stack:`) contribute to
13	//! `LoadPlan.segments` for overlap checks but never produce
14	//! `--load-binary` arguments.
15	
16	use std::collections::BTreeMap;
17	
18	use camino::{Utf8Path, Utf8PathBuf};
19	
20	use crate::config::{Config, LoadMethod, Scenario, SegmentKind, SizeOrAuto};
21	use crate::error::{Error, Result};
22	use crate::tool::Listing;
23	
24	/// Map of `layer name -> (artifact path, listing)`. Filled by the
25	/// step-007 `Assembler` and consumed here. For pure-data layers
26	/// the listing is empty; the artifact path is required.
27	#[derive(Debug, Default, Clone)]
28	pub struct Artifacts {
29	    pub by_layer: BTreeMap<String, ArtifactEntry>,
30	}
31	
32	#[derive(Debug, Clone)]
33	pub struct ArtifactEntry {
34	    pub artifact: Utf8PathBuf,
35	    pub listing: Listing,
36	}
37	
38	/// What to load, where, and what to patch before launching the
39	/// emulator.
40	#[derive(Debug, Clone, Default, PartialEq, Eq)]
41	pub struct LoadPlan {
42	    pub memory_loads: Vec<MemoryLoad>,
43	    pub uart: Vec<UartChunk>,
44	    pub patches: Vec<ResolvedPatch>,
45	    pub entry: u32,
46	    /// Every segment claimed by every layer in the scenario, in
47	    /// declaration order. Embedded segments are included but
48	    /// contribute no MemoryLoad.
49	    pub segments: Vec<ResolvedSegment>,
50	}
51	
52	#[derive(Debug, Clone, PartialEq, Eq)]
53	pub struct MemoryLoad {
54	    pub layer: String,
55	    pub path: Utf8PathBuf,
56	    pub address: u32,
57	}
58	
59	#[derive(Debug, Clone, PartialEq, Eq)]
60	pub struct UartChunk {
61	    pub layer: String,
62	    pub bytes: Vec<u8>,
63	    pub terminator: Option<u8>,
64	}
65	
66	#[derive(Debug, Clone, PartialEq, Eq)]
67	pub struct ResolvedPatch {
68	    pub address: u32,
69	    pub value: u32,
70	}
71	
72	#[derive(Debug, Clone, PartialEq, Eq)]
73	pub struct ResolvedSegment {
74	    pub layer: String,
75	    pub name: Option<String>,
76	    pub kind: SegmentKind,
77	    pub start: u32,
78	    pub end: u32,
79	    pub embedded: bool,
80	}
81	
82	impl LoadPlan {
83	    /// Construct a `LoadPlan` from a config + scenario name +
84	    /// already-built artifacts. Returns `Err` only on shape
85	    /// problems that validation should have caught earlier
86	    /// (missing scenario, missing artifact for a memory layer,
87	    /// unparseable hex).
88	    pub fn build(
89	        cfg: &Config,
90	        scenario_name: &str,
91	        artifacts: &Artifacts,
92	        config_dir: &Utf8Path,
93	    ) -> Result<LoadPlan> {
94	        let scen = cfg
95	            .scenarios
96	            .get(scenario_name)
97	            .ok_or_else(|| Error::cli(format!("scenario `{scenario_name}` not declared")))?;
98	        let mut plan = LoadPlan {
99	            entry: scen.entry.as_u32()?,
100	            ..LoadPlan::default()
101	        };
102	        // Pass 1: memory loads, UART, segments. No patches yet --
103	        // cross-layer patches need every layer's load.address known.
104	        for layer_name in &scen.layers {
105	            let Some(layer) = cfg.layers.get(layer_name) else {
106	                continue;
107	            };
108	            collect_layer(layer_name, layer, artifacts, scen, &mut plan)?;
109	        }
110	        plan.memory_loads.sort_by_key(|m| m.address);
111	        // Pass 2: resolve patches now that the plan knows where
112	        // every layer ended up. Literal hex stays inline; cross-
113	        // layer "<other>.<symbol>" looks up the producing layer's
114	        // listing in `artifacts`; "sidecar:<path>" reads a hex
115	        // value from a build-time text file (relative to
116	        // `config_dir`).
117	        for layer_name in &scen.layers {
118	            let Some(layer) = cfg.layers.get(layer_name) else {
119	                continue;
120	            };
121	            for p in &layer.patches {
122	                if let Some(rp) = resolve_patch(p, layer_name, cfg, artifacts, &plan, config_dir)? {
123	                    plan.patches.push(rp);
124	                }
125	            }
126	        }
127	        plan.patches.sort_by_key(|p| p.address);
128	        Ok(plan)
129	    }
130	
131	    /// Translate this plan into the argv `cor24-run` expects,
132	    /// without spawning anything. Used by step 009 (runner) and
133	    /// by the snapshot tests below.
134	    pub fn cor24_argv(&self) -> Vec<String> {
135	        let mut argv: Vec<String> = Vec::new();
136	        for m in &self.memory_loads {
137	            argv.push("--load-binary".into());
138	            argv.push(format!(
139	                "{path}@0x{addr:06X}",
140	                path = m.path,
141	                addr = m.address
142	            ));
143	        }
144	        for p in &self.patches {
145	            argv.push("--patch".into());
146	            argv.push(format!(
147	                "0x{addr:06X}=0x{value:06X}",
148	                addr = p.address,
149	                value = p.value
150	            ));
151	        }
152	        argv.push("--entry".into());
153	        argv.push(format!("0x{:06X}", self.entry));
154	        if !self.uart.is_empty() {
155	            let mut payload: Vec<u8> = Vec::new();
156	            for chunk in &self.uart {
157	                payload.extend_from_slice(&chunk.bytes);
158	                if let Some(t) = chunk.terminator {
159	                    payload.push(t);
160	                }
161	            }
162	            argv.push("--uart-input".into());
163	            argv.push(String::from_utf8_lossy(&payload).into_owned());
164	        }
165	        argv
166	    }
167	}
168	
169	fn collect_layer(
170	    layer_name: &str,
171	    layer: &crate::config::Layer,
172	    artifacts: &Artifacts,
173	    scen: &Scenario,
174	    plan: &mut LoadPlan,
175	) -> Result<()> {
176	    if let Some(load) = &layer.load {
177	        match load.method {
178	            LoadMethod::Memory => collect_memory(layer_name, layer, load, artifacts, plan)?,
179	            LoadMethod::Uart => collect_uart(layer_name, layer, load, plan)?,
180	        }
181	    }
182	    let _ = scen; // used by step 009 once profile-relative claims resolve
183	    for (idx, seg) in layer.segments.iter().enumerate() {
184	        if let Some(rs) = resolve_segment(layer_name, idx, seg, layer, artifacts) {
185	            plan.segments.push(rs);
186	        }
187	    }
188	    Ok(())
189	}
190	
191	fn collect_memory(
192	    layer_name: &str,
193	    layer: &crate::config::Layer,
194	    load: &crate::config::LoadSpec,
195	    artifacts: &Artifacts,
196	    plan: &mut LoadPlan,
197	) -> Result<()> {
198	    let Some(addr_hex) = &load.address else {
199	        return Ok(());
200	    };
201	    let addr = addr_hex.as_u32()?;
202	    let path = artifacts
203	        .by_layer
204	        .get(layer_name)
205	        .map(|a| a.artifact.clone())
206	        .or_else(|| layer.input.as_deref().map(Utf8PathBuf::from))
207	        .ok_or_else(|| Error::cli(format!("layer `{layer_name}` has no built artifact path")))?;
208	    plan.memory_loads.push(MemoryLoad {
209	        layer: layer_name.into(),
210	        path,
211	        address: addr,
212	    });
213	    Ok(())
214	}
215	
216	fn collect_uart(
217	    layer_name: &str,
218	    layer: &crate::config::Layer,
219	    load: &crate::config::LoadSpec,
220	    plan: &mut LoadPlan,
221	) -> Result<()> {
222	    let bytes = if let Some(input) = &layer.input {
223	        std::fs::read(input).map_err(|source| Error::Io { source })?
224	    } else {
225	        Vec::new()
226	    };
227	    let terminator = load.terminator.as_deref().and_then(|n| match n {
228	        "EOT" => Some(0x04u8),
229	        "ETX" => Some(0x03u8),
230	        "EOF" => Some(0x1Au8),
231	        _ => None,
232	    });
233	    plan.uart.push(UartChunk {
234	        layer: layer_name.into(),
235	        bytes,
236	        terminator,
237	    });
238	    Ok(())
239	}
240	
241	fn resolve_segment(
242	    layer_name: &str,
243	    idx: usize,
244	    seg: &crate::config::Segment,
245	    layer: &crate::config::Layer,
246	    artifacts: &Artifacts,
247	) -> Option<ResolvedSegment> {
248	    let size = seg
249	        .size
250	        .as_ref()
251	        .and_then(SizeOrAuto::as_hex)
252	        .and_then(|h| h.as_u32().ok())
253	        .unwrap_or(0);
254	    let start = if seg.embedded == Some(true) {
255	        let symbol = seg.symbol.as_deref()?;
256	        artifacts
257	            .by_layer
258	            .get(layer_name)?
259	            .listing
260	            .resolve(symbol)?
261	    } else {
262	        seg.load.as_ref()?.address.as_ref()?.as_u32().ok()?
263	    };
264	    let _ = (idx, layer); // placeholders for step 009 partition-claim resolution
265	    Some(ResolvedSegment {
266	        layer: layer_name.into(),
267	        name: seg.name.clone(),
268	        kind: seg.kind,
269	        start,
270	        end: start.saturating_add(size),
271	        embedded: seg.embedded == Some(true),
272	    })
273	}
274	
275	/// Resolve a single `Patch` against the in-progress plan and the
276	/// built `Artifacts`. Targets and values can each be:
277	///
278	///   - literal hex (`"0x000A12"`)
279	///   - cross-layer symbol (`"<layer>.<symbol>"`) -- resolved
280	///     through the producing layer's `Listing` plus its load
281	///     address; the value form `"<layer>.address"` returns the
282	///     layer's load address verbatim.
283	///
284	/// Returns `Ok(None)` if the patch can't be resolved by *shape*
285	/// (e.g. a future `self.address` form); `Err` if the shape is
286	/// supported but resolution failed (missing listing, unknown
287	/// symbol).
288	fn resolve_patch(
289	    p: &crate::config::Patch,
290	    _layer_name: &str,
291	    cfg: &Config,
292	    artifacts: &Artifacts,
293	    plan: &LoadPlan,
294	    config_dir: &Utf8Path,
295	) -> Result<Option<ResolvedPatch>> {
296	    let address = match resolve_patch_term(&p.target, cfg, artifacts, plan, config_dir)? {
297	        Some(a) => a,
298	        None => return Ok(None),
299	    };
300	    let value = match resolve_patch_term(&p.value, cfg, artifacts, plan, config_dir)? {
301	        Some(v) => v,
302	        None => return Ok(None),
303	    };
304	    Ok(Some(ResolvedPatch { address, value }))
305	}
306	
307	/// One of the two halves of a patch (target *or* value). Phase 3
308	/// shapes: hex-literal, `<layer>.<symbol-or-address>`, and
309	/// `sidecar:<path>` (path resolved relative to `config_dir` if
310	/// not absolute; file contents are a single hex value, with or
311	/// without `0x` prefix, whitespace tolerated).
312	fn resolve_patch_term(
313	    term: &str,
314	    cfg: &Config,
315	    artifacts: &Artifacts,
316	    plan: &LoadPlan,
317	    config_dir: &Utf8Path,
318	) -> Result<Option<u32>> {
319	    if term.starts_with("0x") {
320	        return Ok(Some(crate::config::parse_hex_u32(term)?));
321	    }
322	    if term == "self.address" || term == "self.end" || term == "self.size" {
323	        return Ok(None); // resolved by segment-block context, step 010
324	    }
325	    if let Some(rel) = term.strip_prefix("sidecar:") {
326	        let path = if Utf8Path::new(rel).is_absolute() {
327	            Utf8PathBuf::from(rel)
328	        } else {
329	            config_dir.join(rel)
330	        };
331	        let raw = std::fs::read_to_string(path.as_std_path()).map_err(|_| {
332	            Error::cli(format!(
333	                "E0019 sidecar `{path}` could not be read (referenced by patch term `{term}`)"
334	            ))
335	        })?;
336	        let cleaned = raw.trim();
337	        let stripped = cleaned.strip_prefix("0x").unwrap_or(cleaned);
338	        return u32::from_str_radix(stripped, 16).map(Some).map_err(|e| {
339	            Error::cli(format!(
340	                "E0019 sidecar `{path}` does not contain a hex literal (got {cleaned:?}): {e}"
341	            ))
342	        });
343	    }
344	    let Some((layer_name, sym)) = term.split_once('.') else {
345	        return Err(Error::cli(format!(
346	            "E0006 patch term `{term}` is neither hex nor `<layer>.<symbol>`"
347	        )));
348	    };
349	    let load = plan
350	        .memory_loads
351	        .iter()
352	        .find(|m| m.layer == layer_name)
353	        .ok_or_else(|| {
354	            Error::cli(format!(
355	                "E0006 patch term `{term}` references layer `{layer_name}` which has no memory load"
356	            ))
357	        })?;
358	    if sym == "address" {
359	        return Ok(Some(load.address));
360	    }
361	    let _ = cfg;
362	    let entry = artifacts.by_layer.get(layer_name).ok_or_else(|| {
363	        Error::cli(format!(
364	            "E0006 patch term `{term}` references layer `{layer_name}` whose artifact is not built"
365	        ))
366	    })?;
367	    let offset = entry.listing.resolve(sym).ok_or_else(|| {
368	        Error::cli(format!(
369	            "E0006 patch term `{term}` symbol `{sym}` not found in layer `{layer_name}`'s listing"
370	        ))
371	    })?;
372	    Ok(Some(load.address.saturating_add(offset)))
373	}
374

