1	//! Snapshot tests for `manifest::LoadPlan` and the cor24 argv it
2	//! emits. The snapshots are inline strings (no external snapshot
3	//! crate) so a churn in formatting fails loudly here rather than
4	//! later.
5	
6	use std::collections::BTreeMap;
7	
8	use camino::{Utf8Path, Utf8PathBuf};
9	use sw_launcher::config::Config;
10	use sw_launcher::manifest::{ArtifactEntry, Artifacts, LoadPlan};
11	use sw_launcher::tool::Listing;
12	
13	fn scenario_a_toml(input_dir: &Utf8PathBuf) -> String {
14	    format!(
15	        r#"
16	schema_version = 1
17	[project]
18	name = "echo-demo"
19	[targets.cor24]
20	kind = "emulator"
21	word_bits = 24
22	address_bits = 24
23	endian = "big"
24	loader = "cor24-memory-map"
25	regions = {{ sram = {{ start = "0x000000", end = "0x0FFFFF" }}, ebr_stack = {{ start = "0xFEEC00", end = "0xFEF7FF" }}, mmio = {{ start = "0xFF0000", end = "0xFFFFFF" }} }}
26	[scenarios.echo]
27	target = "cor24"
28	layers = ["echo_program", "stdin_data"]
29	entry  = "0x000000"
30	[scenarios.echo.run]
31	max_cycles = 200000
32	[layers.echo_program]
33	kind = "assembler"
34	input = "{input_dir}/echo.s"
35	artifact = "echo.bin"
36	[layers.echo_program.load]
37	method = "memory"
38	address = "0x000000"
39	[layers.stdin_data]
40	kind = "data"
41	input = "{input_dir}/echo-input.txt"
42	[layers.stdin_data.load]
43	method = "uart"
44	max_bytes = 1024
45	terminator = "EOT"
46	"#,
47	        input_dir = input_dir
48	    )
49	}
50	
51	fn parse(s: &str) -> Config {
52	    Config::from_toml_str(s).expect("toml parses")
53	}
54	
55	fn artifacts_for_echo(input_dir: &Utf8PathBuf) -> Artifacts {
56	    let mut by_layer = BTreeMap::new();
57	    by_layer.insert(
58	        "echo_program".to_string(),
59	        ArtifactEntry {
60	            artifact: input_dir.join("echo.bin"),
61	            listing: Listing::default(),
62	        },
63	    );
64	    Artifacts { by_layer }
65	}
66	
67	fn fixtures_dir() -> Utf8PathBuf {
68	    let mut p = Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR"));
69	    p.push("tests/fixtures");
70	    p
71	}
72	
73	#[test]
74	fn scenario_a_load_plan_has_expected_shape() {
75	    let dir = fixtures_dir();
76	    let cfg = parse(&scenario_a_toml(&dir));
77	    let arts = artifacts_for_echo(&dir);
78	    let plan = LoadPlan::build(&cfg, "echo", &arts, Utf8Path::new(".")).expect("plan builds");
79	
80	    assert_eq!(plan.entry, 0x000000);
81	    assert_eq!(plan.memory_loads.len(), 1);
82	    assert_eq!(plan.memory_loads[0].layer, "echo_program");
83	    assert_eq!(plan.memory_loads[0].address, 0x000000);
84	    assert_eq!(plan.uart.len(), 1);
85	    assert_eq!(plan.uart[0].layer, "stdin_data");
86	    assert_eq!(plan.uart[0].terminator, Some(0x04));
87	    assert!(plan.patches.is_empty());
88	    assert!(plan.segments.is_empty());
89	}
90	
91	#[test]
92	fn scenario_a_argv_matches_golden() {
93	    let dir = fixtures_dir();
94	    let cfg = parse(&scenario_a_toml(&dir));
95	    let arts = artifacts_for_echo(&dir);
96	    let plan = LoadPlan::build(&cfg, "echo", &arts, Utf8Path::new(".")).unwrap();
97	    let argv = plan.cor24_argv();
98	    let bin = dir.join("echo.bin");
99	    let expected: Vec<String> = vec![
100	        "--load-binary".into(),
101	        format!("{bin}@0x000000"),
102	        "--entry".into(),
103	        "0x000000".into(),
104	        "--uart-input".into(),
105	        "abc!\n\u{04}".into(),
106	    ];
107	    assert_eq!(argv, expected, "argv:\n{argv:#?}\nexpected:\n{expected:#?}");
108	}
109	
110	const SCENARIO_A_WITH_EMBEDDED_TOML: &str = r#"
111	schema_version = 1
112	[project]
113	name = "with-embedded"
114	[targets.cor24]
115	kind = "emulator"
116	word_bits = 24
117	address_bits = 24
118	endian = "big"
119	loader = "cor24-memory-map"
120	regions = { sram = { start = "0x000000", end = "0x0FFFFF" }, ebr_stack = { start = "0xFEEC00", end = "0xFEF7FF" }, mmio = { start = "0xFF0000", end = "0xFFFFFF" } }
121	[scenarios.echo]
122	target = "cor24"
123	layers = ["pvm"]
124	entry  = "0x000000"
125	[scenarios.echo.run]
126	max_cycles = 100000
127	[layers.pvm]
128	kind = "assembler"
129	input = "pvm.s"
130	artifact = "pvm.bin"
131	[layers.pvm.load]
132	method = "memory"
133	address = "0x000000"
134	[[layers.pvm.segments]]
135	name = "eval_stack"
136	kind = "stack"
137	embedded = true
138	symbol = "eval_stack"
139	size = "0x000400"
140	[[layers.pvm.segments]]
141	name = "call_stack"
142	kind = "stack"
143	embedded = true
144	symbol = "call_stack"
145	size = "0x000800"
146	[[layers.pvm.segments]]
147	name = "heap_seg"
148	kind = "heap"
149	embedded = true
150	symbol = "heap_seg"
151	size = "0x002000"
152	"#;
153	
154	#[test]
155	fn embedded_segments_contribute_to_segments_but_not_loads() {
156	    // Synthesize a fake listing with the three embedded labels at
157	    // believable offsets.
158	    let lst_text = "                    _start:\n\
159	                    0000: 00 00 00       .word 0\n\
160	                                        eval_stack:\n\
161	                    0010: 00 00 00 00    .skip 1024\n\
162	                                        call_stack:\n\
163	                    0410: 00             .skip 2048\n\
164	                                        heap_seg:\n\
165	                    0C10: 00             .skip 8192\n";
166	    let listing = Listing::parse(lst_text);
167	    assert_eq!(listing.resolve("eval_stack"), Some(0x0010));
168	    assert_eq!(listing.resolve("call_stack"), Some(0x0410));
169	    assert_eq!(listing.resolve("heap_seg"), Some(0x0C10));
170	
171	    let mut by_layer = BTreeMap::new();
172	    by_layer.insert(
173	        "pvm".to_string(),
174	        ArtifactEntry {
175	            artifact: fixtures_dir().join("pvm.bin"),
176	            listing,
177	        },
178	    );
179	    let arts = Artifacts { by_layer };
180	    let cfg = parse(SCENARIO_A_WITH_EMBEDDED_TOML);
181	    let plan = LoadPlan::build(&cfg, "echo", &arts, Utf8Path::new(".")).unwrap();
182	
183	    // Memory loads: only the layer's bin (one); embedded segments
184	    // do NOT add --load-binary entries.
185	    assert_eq!(plan.memory_loads.len(), 1);
186	    let argv = plan.cor24_argv();
187	    let load_count = argv.iter().filter(|s| s == &"--load-binary").count();
188	    assert_eq!(load_count, 1, "embedded segments must not emit loads");
189	
190	    // segments: three embedded ranges, addresses resolved through
191	    // the listing, sizes from TOML.
192	    assert_eq!(plan.segments.len(), 3);
193	    assert_eq!(plan.segments[0].name.as_deref(), Some("eval_stack"));
