exports = { symbols = ["code_ptr"] }
[layers.vm.load]
method = "memory"
address = "0x000000"
[layers.app]
kind = "binary"
input = "app.bin"
patches = [
  { target = "vm.code_ptr", value = "0x010000" },
]
[layers.app.load]
method = "memory"
address = "0x010000"
"#;
    let cfg = parse(toml);
    let mut by_layer = BTreeMap::new();
    let lst = "                    _start:\n\
               0000: 00 00 00       .word 0\n\
                                    code_ptr:\n\
               0010: 00 00 00       .word 0\n";
    by_layer.insert(
        "vm".to_string(),
        ArtifactEntry {
            artifact: Utf8PathBuf::from("vm.bin"),
            listing: Listing::parse(lst),
